{
  "$schema": "https://opencode.ai/config.json",
  "default_agent": "jarvis",
  "agent": {
    "jarvis": {
      "mode": "primary",
      "description": "Primary agent for managing Daniel Lacemore's Obsidian vault",
      "temperature": 0.1,
      "color": "#8B5CF6",
      "prompt": "{file:./.prompts/jarvis.md}",
      "permission": {
        "*": "allow",
        "task": {
          "translator": "allow",
          "archie": "allow",
          "friday": "allow",
          "melio": "allow",
          "socrates": "allow"
        }
      }
    },
    "translator": {
      "mode": "subagent",
      "description": "Obsidian notes translator between your primary and secondary language (default English <-> Italian)",
      "prompt": "{file:./.prompts/translator.md}"
    },
    "archie": {
      "mode": "subagent",
      "description": "Senior Solution Architect specialized in technical proposals for Data & GenAI projects. Operates as a subagent inside Daniel's Obsidian vault, under Jarvis's orchestration.",
      "prompt": "{file:./.prompts/archie.md}"
    },
    "friday": {
      "mode": "subagent",
      "description": "Agent specialized in generating HTML/CSS presentations from the textual deliverables produced by Archie. Operates as a subagent inside Daniel's Obsidian vault, under Jarvis's orchestration.",
      "prompt": "{file:./.prompts/friday.md}"
    },
    "melio": {
      "mode": "subagent",
      "description": "Agent specialized in gathering ideas, hints and suggestions to improve the organization of Daniel's Obsidian vault. Operates as a subagent inside the vault, under Jarvis's orchestration.",
      "prompt": "{file:./.prompts/melio.md}"
    },
    "socrates": {
      "mode": "all",
      "description": "Directly selectable agent dedicated to dialogic brainstorming: it develops ideas through progressive questions and understandable language, without modifying the vault.",
      "temperature": 0.6,
      "color": "#D97706",
      "prompt": "{file:./.prompts/socrates.md}",
      "permission": {
        "edit": "deny",
        "bash": "deny",
        "task": "deny",
        "todowrite": "deny",
        "websearch": "allow",
        "webfetch": "allow"
      }
    }
  }
}
